function renderMessageText(rawText) {
  const safe = esc(rawText);
  const withEmoji = safe.replace(/:([a-z0-9_]+):/gi, (whole, name) => {
    const key = name.toLowerCase();
    if (customEmojis[key]) return `<img class="custom-emoji" src="${customEmojis[key].dataUrl}" alt=":${esc(key)}:" title=":${esc(key)}:">`;
    if (SHORTCODE_MAP[key]) return `<span class="native-emoji">${SHORTCODE_MAP[key]}</span>`;
    return whole;
  });
  // @mentions only "glow" when that user is actually in the current
  // server/DM/group, or it's an @everyone/@here broadcast mention (those
  // always count, regardless of context) — otherwise it renders as a
  // plain, dim mention.
  const contextMembers = currentContextUsernames();
  const withMentions = withEmoji.replace(/(^|[\s(>])@([A-Za-z0-9_]{3,24})\b/g, (whole, lead, name) => {
    const lower = name.toLowerCase();
    const isBroadcast = lower === 'everyone' || lower === 'here';
    const inContext = isBroadcast || contextMembers.includes(name);
    // A misspelled or nonexistent mention isn't a real ping — leave it as
    // plain text entirely rather than giving it any pill styling at all,
    // dim or otherwise, so only mentions that actually resolve stand out.
    if (!inContext) return whole;
    const cls = 'mention-pill mention-glow' + (name === myUid ? ' mention-self' : '');
    return `${lead}<span class="${cls}">@${esc(name)}</span>`;
  });
  return linkifyText(withMentions);
}
// Same matching rules as the @mention renderer above, kept in sync
// deliberately — this decides whether a message plays a ping sound for the
// current viewer specifically. @here is treated the same as @everyone here
// (rather than only pinging users currently online) since precisely
// tracking "was I online the instant this was sent" isn't worth the
// complexity for what's fundamentally the same "hey, pay attention" signal.
function messageTextMentionsMe(text) {
  if (!text || !myUid) return false;
  const re = /(^|[\s(>])@([A-Za-z0-9_]{3,24})\b/g;
  let match;
  while ((match = re.exec(text))) {
    const lower = match[2].toLowerCase();
    if (lower === 'everyone' || lower === 'here' || match[2] === myUid) return true;
  }
  return false;
}

// Runs last, after emoji/mention HTML has already been injected — the
// character class excludes <, >, " and ' so a match can never span across
// an already-inserted tag or break out of the href attribute it gets
// placed into.
function linkifyText(html) {
  return html.replace(/\b((?:https?:\/\/|www\.)[^\s<>"']+)/gi, (match) => {
    // Trim trailing punctuation that's almost always sentence punctuation
    // rather than part of the link, but keep a closing bracket/paren that
    // balances one earlier in the URL.
    let url = match;
    let trail = '';
    while (url.length) {
      const last = url[url.length - 1];
      if (!/[.,!?;:'")\]]/.test(last)) break;
      if (last === ')' && (url.match(/\(/g) || []).length > (url.match(/\)/g) || []).length) break;
      if (last === ']' && (url.match(/\[/g) || []).length > (url.match(/\]/g) || []).length) break;
      trail = last + trail;
      url = url.slice(0, -1);
    }
    if (!url) return match;
    const href = (/^https?:\/\//i.test(url) ? url : 'https://' + url).replace(/"/g, '&quot;');
    return `<a href="${href}" target="_blank" rel="noopener noreferrer" class="msg-link">${url}</a>${trail}`;
  });
}

// ---------- message filter ----------
// Bypass-resistant: matches leetspeak substitutions, repeated letters, and
// letters split up with punctuation/spaces — but only as a WHOLE word, so it
// won't flag normal words that merely contain a filtered word as a substring
// (e.g. filtering "ass" will not touch "class" or "assist").
const LEET_CLASSES = { a: 'a4@', b: 'b8', e: 'e3', g: 'g9', i: 'i1!|', l: 'l1', o: 'o0', s: 's5$', t: 't7', z: 'z2' };
let filteredWords = [];
function subscribeMessageFilter() {
  db.collection('config').doc('filter').onSnapshot(snap => {
    filteredWords = (snap.exists && Array.isArray(snap.data().words)) ? snap.data().words : [];
    if (!$('admin-panel-modal').classList.contains('hidden')) renderAdminFilterList();
  });
}
function buildFilterRegex(word) {
  const chars = word.toLowerCase().split('').filter(c => /[a-z0-9]/.test(c));
  if (!chars.length) return null;
  const parts = chars.map(c => (LEET_CLASSES[c] ? `[${LEET_CLASSES[c]}]` : c) + '+');
  const body = parts.join('[^a-z0-9]*');
  try { return new RegExp(`(?<![a-z0-9])${body}(?![a-z0-9])`, 'gi'); } catch (e) { return null; }
}
function applyMessageFilter(text) {
  let out = text;
  for (const w of filteredWords) {
    const re = buildFilterRegex(w);
    if (re) out = out.replace(re, '[CENSORED]');
  }
  return out;
}

