  currentView = 'none'; currentDMId = null; currentDMOtherUid = null; currentGroupDMId = null;
  if (unsub.channels) { unsub.channels(); unsub.channels = null; }
  if (unsub.categories) { unsub.categories(); unsub.categories = null; }
