  let top = r.bottom + 6;
  if (top + popH > window.innerHeight - 8) top = Math.max(8, r.top - popH - 6);
  panel.style.left = `${left}px`;
  panel.style.top = `${top}px`;
  panel.classList.remove('hidden');
