async function submitPoll() {
  const question = $('poll-question').value.trim();
  if (!question) { toast('Please enter a poll question.', 'error'); return; }
  const answers = [...$('poll-answer-list').querySelectorAll('.poll-answer-row')]
    .map(row => ({ text: row.querySelector('.poll-answer-input').value.trim(), emoji: row.dataset.emoji || null }))
    .filter(a => a.text);
  if (answers.length < 2) { toast('Add at least 2 answers.', 'error'); return; }
  if (currentView !== 'channel' && currentView !== 'dm' && currentView !== 'groupdm') { toast('Pick a conversation first.'); return; }
  const durationMs = parseInt($('poll-duration').value, 10) || 86400000;
  const allowMultiple = $('poll-multiple').checked;
  const payload = {
    uid: myUid, username: myProfile.username, createdAt: FieldValue.serverTimestamp(),
    type: 'poll',
    poll: {
      question, answers, allowMultiple,
      expiresAt: firebase.firestore.Timestamp.fromMillis(Date.now() + durationMs),
      votes: {},
    },
  };
  const btn = $('poll-submit');
  btn.disabled = true;
  try {
    await sendToCurrentConversation(payload);
    closeModal('poll-modal');
    toast('Poll posted.');
  } catch (e) { toast(e.message || 'Could not post the poll.', 'error'); }
  finally { btn.disabled = false; }
}
$('poll-submit').onclick = submitPoll;
// Closing the poll modal (X or Cancel) while its emoji picker is open
// shouldn't leave that panel floating over the chat behind it.
document.querySelectorAll('#poll-modal [data-close="poll-modal"]').forEach(el => {
  el.addEventListener('click', closeEmojiPickerPanel);
});

async function sendToCurrentConversation(payload) {
  let ref;
  if (currentView === 'channel') {
    ref = await db.collection('servers').doc(currentServerId).collection('channels').doc(currentChannelId).collection('messages').add(payload);
    db.collection('users').doc(myUid).update({ 'dailyStats.channelsMessaged': FieldValue.increment(1) }).catch(() => {});
  } else if (currentView === 'dm') {
    ref = await db.collection('dms').doc(currentDMId).collection('messages').add(payload);
    await db.collection('dms').doc(currentDMId).update({
      updatedAt: FieldValue.serverTimestamp(),
      lastMessage: { text: previewForMessage(payload), username: myProfile.username },
    });
    db.collection('users').doc(myUid).update({ 'dailyStats.dmsMessaged': FieldValue.increment(1) }).catch(() => {});
  } else if (currentView === 'groupdm') {
    ref = await db.collection('groupDMs').doc(currentGroupDMId).collection('messages').add(payload);
    await db.collection('groupDMs').doc(currentGroupDMId).update({
      updatedAt: FieldValue.serverTimestamp(),
      lastMessage: { text: previewForMessage(payload), username: myProfile.username },
    });
    db.collection('users').doc(myUid).update({ 'dailyStats.dmsMessaged': FieldValue.increment(1) }).catch(() => {});
  } else {
    throw new Error('No conversation selected.');
  }
  db.collection('users').doc(myUid).update({
    'stats.messagesSent': FieldValue.increment(1),
    'dailyStats.messagesSent': FieldValue.increment(1),
  }).catch(() => {});
  return ref;
}

// Posts a message on behalf of a bot (e.g. Sapphire). Deliberately doesn't
// reuse sendToCurrentConversation — that function always credits myUid's
// own stats/quests, which shouldn't happen for something the bot sent.
async function postBotMessage(payload) {
  const coll = msgCollectionRef();
  if (!coll) return;
  await coll.add(payload);
  const preview = { text: previewForMessage(payload), username: payload.username };
  if (currentView === 'dm') {
    await db.collection('dms').doc(currentDMId).update({ updatedAt: FieldValue.serverTimestamp(), lastMessage: preview });
  } else if (currentView === 'groupdm') {
    await db.collection('groupDMs').doc(currentGroupDMId).update({ updatedAt: FieldValue.serverTimestamp(), lastMessage: preview });
  }
}

const SAPPHIRE_PURGE_MAX = 1000; // safety ceiling when an explicit count is given
const SAPPHIRE_PURGE_BATCH_SIZE = 450; // stay safely under Firestore's 500-op batch cap
async function runPurgeCommand(rawCountText) {
  if (!isAdmin && !isOwner) { toast('Only admins can use /purge.', 'error'); return; }
  if (currentView !== 'channel' && currentView !== 'dm' && currentView !== 'groupdm') { toast('Pick a conversation first.'); return; }
  const parsed = parseInt(rawCountText, 10);
  const n = Number.isFinite(parsed) && parsed > 0 ? Math.min(SAPPHIRE_PURGE_MAX, parsed) : null; // no count → delete everything
  const coll = msgCollectionRef();
  if (!coll) return;
  try {
    // No count given: /purge wipes the whole conversation, bot messages
    // included. The command echo below is posted *after* this deletion pass
    // so it survives this run, but since the next /purge deletes everything
    // (not just a bounded window), that echo — and this run's confirmation
    // card — get swept up automatically next time, instead of piling up.
    const query = n ? coll.orderBy('createdAt', 'desc').limit(n) : coll;
    const snap = await query.get();
    const docs = snap.docs;
    for (let i = 0; i < docs.length; i += SAPPHIRE_PURGE_BATCH_SIZE) {
      const batch = db.batch();
      docs.slice(i, i + SAPPHIRE_PURGE_BATCH_SIZE).forEach(d => batch.delete(d.ref));
      await batch.commit();
    }
    const purgeText = rawCountText ? `/purge ${rawCountText}` : '/purge';
    const echoRef = await sendToCurrentConversation({
      text: purgeText,
      uid: myUid, username: myProfile.username, createdAt: FieldValue.serverTimestamp(),
    });
    await postBotMessage({
      uid: SAPPHIRE_BOT_UID, username: SAPPHIRE_BOT_PROFILE.username, createdAt: FieldValue.serverTimestamp(),
      purgeResult: { count: docs.length },
      replyTo: echoRef ? { id: echoRef.id, uid: myUid, username: myProfile.username, text: purgeText } : null,
    });
  } catch (e) { toast(e.message || 'Could not purge messages.', 'error'); }
}

async function sendMessage() {
  const input = $('composer-input');
  const sendChannel = currentView === 'channel' ? currentChannelObj() : null;
  if (sendChannel && currentServerData && !hasChannelPerm(sendChannel, currentServerData, myUid, 'sendMessages')) {
    toast('You do not have permission to send messages in this channel.');
    return;
  }
  if (sendChannel && input.value.trim() && slowmodeRemaining(sendChannel) > 0) {
    toast(`Slowmode is on. You can send another message in ${slowmodeRemaining(sendChannel)}s.`);
    return;
  }
  const raw = input.value.trim();
  const pendingAttachments = draftAttachments.slice();
  // Typing "/poll" alone and hitting Enter opens the poll composer instead
  // of sending it as a message — same trigger word, but it now behaves
  // like every other slash command (acts on send, not on keystroke), and
  // the "/poll" text is cleared the same way any other sent text would be.
  if (!pendingAttachments.length && raw.toLowerCase() === '/poll') {
    input.value = '';
    autoResize(input);
    updateComposerCharCount();
    clearMyTypingDoc();
    closeMentionPopup();
    openPollModal();
    return;
  }
  // "/purge <n>" — admin-only, deletes the last n messages in the current
  // conversation and has Sapphire post a confirmation card.
  const purgeMatch = !pendingAttachments.length ? /^\/purge(?:\s+(\d+))?$/i.exec(raw) : null;
  if (purgeMatch) {
    input.value = '';
    autoResize(input);
    updateComposerCharCount();
    clearMyTypingDoc();
    closeMentionPopup();
    runPurgeCommand(purgeMatch[1]);
    return;
  }
  if (!raw && !pendingAttachments.length) return;
  if (currentView !== 'channel' && currentView !== 'dm' && currentView !== 'groupdm') { toast('Pick a conversation first.'); return; }
  if (raw.length > COMPOSER_MAX_LENGTH) { toast(`Your message is ${raw.length - COMPOSER_MAX_LENGTH} characters over the limit.`, 'error'); return; }
  if (sendChannel && sendChannel.slowmode) { lastChannelSendAt[sendChannel.id] = Date.now(); renderSlowmodeIndicator(); }
  input.value = '';
  autoResize(input);
  updateComposerCharCount();
  clearMyTypingDoc();
  closeMentionPopup();
  draftAttachments = [];
  renderAttachmentDraft();
  const text = raw ? applyMessageFilter(raw) : '';
  const payload = { text, uid: myUid, username: myProfile.username, createdAt: FieldValue.serverTimestamp() };
  if (replyTarget) payload.replyTo = { id: replyTarget.id, uid: replyTarget.uid, username: replyTarget.username, text: replyTarget.text };
  try {
    if (pendingAttachments.length) {
      const bar = $('upload-progress');
      bar.classList.remove('hidden');
      bar.innerHTML = `<div class="spinner small"></div><span>Uploading ${pendingAttachments.length > 1 ? pendingAttachments.length + ' files' : esc(pendingAttachments[0].file.name)}…</span>`;
      const uploaded = [];
      for (const d of pendingAttachments) {
        const url = await uploadFileGeneric(d.file, d.type === 'image');
        uploaded.push({ url, type: d.type, name: d.file.name, size: d.file.size });
        if (d.previewUrl) URL.revokeObjectURL(d.previewUrl);
      }
      bar.classList.add('hidden');
      payload.attachments = uploaded;
    }
    await sendToCurrentConversation(payload);
    clearReplyTarget();
  } catch (e) {
    $('upload-progress').classList.add('hidden');
    toast(e.message || 'Failed to send message.', 'error');
  }
}
// No explicit Send button — matches Discord's real composer (Enter to send).
$('composer-input').addEventListener('keydown', (e) => {
  if (mentionState) {
    if (e.key === 'Tab' || e.key === 'Enter') { e.preventDefault(); completeMention(mentionCandidates[mentionSelectedIndex]); return; }
    if (e.key === 'ArrowDown') { e.preventDefault(); mentionSelectedIndex = (mentionSelectedIndex + 1) % mentionCandidates.length; renderMentionPopup(); return; }
    if (e.key === 'ArrowUp') { e.preventDefault(); mentionSelectedIndex = (mentionSelectedIndex - 1 + mentionCandidates.length) % mentionCandidates.length; renderMentionPopup(); return; }
    if (e.key === 'Escape') { closeMentionPopup(); return; }
  }
  if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); ckWordBoundaryCheck(e.target); sendMessage(); }
});
// Autocorrect on desktop: the word-boundary check only ran through the
// mobile custom keyboard's own key handlers before, so a real keyboard
// typing space never triggered it. This covers that path; Enter is
// handled above right before sendMessage() clears the field.
$('composer-input').addEventListener('keyup', (e) => {
  if (e.key === ' ' && !(ckField && ckField.el === e.target)) ckWordBoundaryCheck(e.target);
});
function autoResize(el) { el.style.height = 'auto'; el.style.height = Math.min(el.scrollHeight, 200) + 'px'; }

// ---------- composer character count ----------
// Positioned with CSS (position:absolute, tucked into the composer's own
// corner) so showing/hiding it never changes the composer bar's height.
const COMPOSER_MAX_LENGTH = 1000;
const COMPOSER_COUNT_SHOW_AT = 100; // only surface it once you're within 100 chars of the cap
function updateComposerCharCount() {
  const counter = $('composer-char-count');
  if (!counter) return;
  const len = $('composer-input').value.length;
  const remaining = COMPOSER_MAX_LENGTH - len;
  if (remaining > COMPOSER_COUNT_SHOW_AT) { counter.classList.add('hidden'); return; }
  counter.classList.remove('hidden');
  const over = remaining < 0;
  counter.classList.toggle('over-limit', over);
  counter.textContent = over ? `-${Math.abs(remaining)}` : `${remaining}`;
}

// ---------- typing indicator ----------
// Presence is a small doc per-user under a `typing` subcollection on
// whichever conversation is open. Writes are throttled (not one per
// keystroke) and self-expire client-side; a staleness check on the reading
// side also ignores anything too old, in case a tab closed without ever
// clearing its own doc.
const TYPING_WRITE_INTERVAL_MS = 4000;
const TYPING_IDLE_MS = 5000;
const TYPING_STALE_MS = 8000;
let typingDocRef = null;
let typingIdleTimer = null;
let lastTypingWriteAt = 0;

function typingCollectionRef() {
  if (currentView === 'channel') return db.collection('servers').doc(currentServerId).collection('channels').doc(currentChannelId).collection('typing');
  if (currentView === 'dm') return db.collection('dms').doc(currentDMId).collection('typing');
  if (currentView === 'groupdm') return db.collection('groupDMs').doc(currentGroupDMId).collection('typing');
  return null;
}

function clearMyTypingDoc() {
  if (typingIdleTimer) { clearTimeout(typingIdleTimer); typingIdleTimer = null; }
  if (typingDocRef) { const ref = typingDocRef; typingDocRef = null; ref.delete().catch(() => {}); }
  lastTypingWriteAt = 0;
}

function noteComposerTyping() {
  if (!myUid) return;
  const coll = typingCollectionRef();
  if (!coll) return;
  const hasText = $('composer-input').value.trim().length > 0;
  if (!hasText) { clearMyTypingDoc(); return; }
  const ref = coll.doc(myUid);
  typingDocRef = ref;
  const now = Date.now();
  if (now - lastTypingWriteAt > TYPING_WRITE_INTERVAL_MS) {
    lastTypingWriteAt = now;
    ref.set({ username: myProfile.username, updatedAt: FieldValue.serverTimestamp() }).catch(() => {});
  }
  if (typingIdleTimer) clearTimeout(typingIdleTimer);
  typingIdleTimer = setTimeout(() => { if (typingDocRef) { const r = typingDocRef; typingDocRef = null; r.delete().catch(() => {}); } }, TYPING_IDLE_MS);
}

function renderTypingIndicator(names) {
  const el = $('typing-indicator');
  if (!el) return;
  if (!names.length) { el.innerHTML = ''; return; }
  let text;
  if (names.length === 1) text = `${names[0]} is typing...`;
  else if (names.length === 2) text = `${names[0]} and ${names[1]} are typing...`;
  else text = `${names[0]} and ${names.length - 1} others are typing...`;
  el.innerHTML = `<span class="typing-dots"><span></span><span></span><span></span></span><span>${esc(text)}</span>`;
}

function subscribeTyping() {
  if (unsub.typing) { unsub.typing(); unsub.typing = null; }
  const coll = typingCollectionRef();
  if (!coll) { renderTypingIndicator([]); return; }
  unsub.typing = coll.onSnapshot(snap => {
    const now = Date.now();
    const names = [];
    snap.forEach(d => {
      if (d.id === myUid) return;
      const data = d.data();
      const ts = data.updatedAt && data.updatedAt.toMillis ? data.updatedAt.toMillis() : 0;
      if (ts && now - ts > TYPING_STALE_MS) return;
      names.push(data.username || d.id);
    });
    renderTypingIndicator(names);
  });
}
$('composer-input').addEventListener('input', (e) => { autoResize(e.target); updateMentionState(e.target); updateComposerCharCount(); noteComposerTyping(); });

// ============================================================
// MENTIONS (@ autocomplete + rendering)
// Typing "@" plus a few letters pops up matching members from whichever
// server/DM/group is currently open, top match highlighted; Tab, Enter,
// or tapping a row completes it (see positionMentionPopup — reuses the
// same caret-measuring trick as the mobile keyboard's cursor overlay).
// Rendered mentions only get the "glow" style when that user is actually
// in the current conversation.
// ============================================================
function currentContextUsernames() {
  if (currentView === 'channel' && currentServerData) return currentServerData.members || [];
  if (currentView === 'dm') return [myUid, currentDMOtherUid].filter(Boolean);
  if (currentView === 'groupdm') {
    const g = (window.__myGroupDMs || []).find(x => x.id === currentGroupDMId);
    return g ? (g.participants || []) : [];
  }
  return [];
}

let mentionState = null;      // { el, start, query } — start is the index of "@" in el.value
let mentionCandidates = [];
let mentionSelectedIndex = 0;

function updateMentionState(el) {
  const pos = el.selectionStart;
  if (pos == null) { closeMentionPopup(); return; }
  const before = el.value.slice(0, pos);
  const m = /(?:^|\s)@([A-Za-z0-9_]{0,24})$/.exec(before);
  if (!m) { closeMentionPopup(); return; }
  const query = m[1];
  const start = pos - query.length - 1;
  const lowerQ = query.toLowerCase();
  const candidates = currentContextUsernames()
    .filter(u => u && u.toLowerCase().startsWith(lowerQ))
    .sort((a, b) => a.toLowerCase().localeCompare(b.toLowerCase()))
    .slice(0, 6);
  if (!candidates.length) { closeMentionPopup(); return; }
  mentionState = { el, start, query };
  mentionCandidates = candidates;
  mentionSelectedIndex = 0;
  renderMentionPopup();
}
function closeMentionPopup() {
  mentionState = null; mentionCandidates = []; mentionSelectedIndex = 0;
  $('mention-popup').classList.add('hidden');
}
function positionMentionPopup(el) {
  const popup = $('mention-popup');
  const fRect = el.getBoundingClientRect();
  const off = measureCaretOffset(el);
  popup.style.left = Math.max(8, Math.min(fRect.left + off.x - (el.scrollLeft || 0), window.innerWidth - popup.offsetWidth - 8)) + 'px';
  popup.style.bottom = (window.innerHeight - fRect.top + 8) + 'px';
}
function renderMentionPopup() {
  const popup = $('mention-popup');
  popup.innerHTML = mentionCandidates.map((u, i) => {
    const p = profileCache[u] || { username: u, avatarColor: '#5865f2' };
    return `<div class="mention-row${i === mentionSelectedIndex ? ' selected' : ''}" data-idx="${i}">
      ${avatarHTML(22, p.avatarColor, initials(p.username), null, p.avatarUrl)}
      <span class="mention-row-name">${esc(p.username)}</span>
      ${u === myUid ? '<span class="mention-row-you">you</span>' : ''}
    </div>`;
  }).join('') + `<div class="mention-hint">Tab to autofill</div>`;
  popup.classList.remove('hidden');
  popup.querySelectorAll('.mention-row').forEach(row => {
    row.onclick = () => completeMention(mentionCandidates[+row.dataset.idx]);
  });
  positionMentionPopup(mentionState.el);
}
function completeMention(username) {
  if (!mentionState || username == null) return;
  const { el, start, query } = mentionState;
  const before = el.value.slice(0, start);
  const after = el.value.slice(start + 1 + query.length);
  const insertion = '@' + username + ' ';
  el.value = before + insertion + after;
  el.selectionStart = el.selectionEnd = before.length + insertion.length;
  closeMentionPopup();
  autoResize(el);
  ckFireInput(el);
  if (ckField && ckField.el === el) positionCkCursor();
}
document.addEventListener('click', (e) => {
  if (!mentionState) return;
  if (e.target.closest('#mention-popup') || e.target.closest('#composer-input')) return;
  closeMentionPopup();
});

