// ---------- Avatar Decoration drawing editor (admin/owner only) ----------
let decoEditorInitialized = false;
let decoMode = 'draw'; // 'draw' | 'emoji' — the emoji path skips needing any drawing skill
let decoDrawing = false;
let decoBrushSize = 7;
let decoErasing = false;
let decoLastX = 0;
let decoLastY = 0;

function decorationEditorCanvasIsBlank(canvas) {
  const ctx = canvas.getContext('2d');
  const data = ctx.getImageData(0, 0, canvas.width, canvas.height).data;
  for (let i = 3; i < data.length; i += 4) { if (data[i] !== 0) return false; }
  return true;
}

function updateDecorationPreview() {
  const canvas = $('deco-draw-canvas');
  const wrap = $('deco-preview-avatar');
  if (!wrap || !myProfile) return;
  const dataUrl = canvas.toDataURL('image/png');
  const blank = decorationEditorCanvasIsBlank(canvas);
  wrap.innerHTML = avatarHTML(64, myProfile.avatarColor, initials(myProfile.username), null, myProfile.avatarUrl, null);
  if (!blank) {
    // Preview the in-progress drawing directly, without needing it saved
    // anywhere yet — same overlay sizing math as a real equipped decoration.
    const decoSize = Math.round(64 * 1.3);
    const decoOffset = Math.round((decoSize - 64) / 2);
    wrap.querySelector('.avatar').insertAdjacentHTML('beforeend',
      `<span class="avatar-decoration" style="width:${decoSize}px;height:${decoSize}px;left:${-decoOffset}px;top:${-decoOffset}px;"><img src="${dataUrl}" alt=""></span>`);
  }
}

function decoCanvasPoint(canvas, e) {
  const rect = canvas.getBoundingClientRect();
  const scaleX = canvas.width / rect.width;
  const scaleY = canvas.height / rect.height;
  return { x: (e.clientX - rect.left) * scaleX, y: (e.clientY - rect.top) * scaleY };
}

function initDecorationEditor() {
  if (decoEditorInitialized) { updateDecorationPreview(); return; }
  decoEditorInitialized = true;
  const canvas = $('deco-draw-canvas');
  const ctx = canvas.getContext('2d');
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  document.querySelectorAll('.deco-mode-btn').forEach(btn => {
    btn.onclick = () => {
      decoMode = btn.dataset.decoMode;
      document.querySelectorAll('.deco-mode-btn').forEach(b => b.classList.toggle('on', b === btn));
      $('deco-mode-draw').classList.toggle('hidden', decoMode !== 'draw');
      $('deco-draw-hint').classList.toggle('hidden', decoMode !== 'draw');
      $('deco-mode-emoji').classList.toggle('hidden', decoMode !== 'emoji');
    };
  });
  $('deco-emoji-input').addEventListener('input', () => {
    $('deco-emoji-preview').textContent = $('deco-emoji-input').value || '🎩';
  });

  const startDraw = (e) => {
    decoDrawing = true;
    const p = decoCanvasPoint(canvas, e);
    decoLastX = p.x; decoLastY = p.y;
    // A single click/tap with no drag should still leave a dot.
    ctx.globalCompositeOperation = decoErasing ? 'destination-out' : 'source-over';
    ctx.fillStyle = $('deco-color-input').value;
    ctx.beginPath();
    ctx.arc(p.x, p.y, decoBrushSize / 2, 0, Math.PI * 2);
    ctx.fill();
  };
  const moveDraw = (e) => {
    if (!decoDrawing) return;
    const p = decoCanvasPoint(canvas, e);
    ctx.globalCompositeOperation = decoErasing ? 'destination-out' : 'source-over';
    ctx.strokeStyle = $('deco-color-input').value;
    ctx.lineWidth = decoBrushSize;
    ctx.beginPath();
    ctx.moveTo(decoLastX, decoLastY);
    ctx.lineTo(p.x, p.y);
    ctx.stroke();
    decoLastX = p.x; decoLastY = p.y;
  };
  const endDraw = () => { if (decoDrawing) { decoDrawing = false; updateDecorationPreview(); } };

  canvas.addEventListener('pointerdown', (e) => { canvas.setPointerCapture(e.pointerId); startDraw(e); });
  canvas.addEventListener('pointermove', moveDraw);
  canvas.addEventListener('pointerup', endDraw);
  canvas.addEventListener('pointerleave', endDraw);

  document.querySelectorAll('.deco-size-btn').forEach(btn => {
    btn.onclick = () => {
      document.querySelectorAll('.deco-size-btn').forEach(b => b.classList.remove('on'));
      btn.classList.add('on');
      decoBrushSize = parseInt(btn.dataset.size, 10);
    };
  });
  $('deco-eraser-btn').onclick = () => {
    decoErasing = !decoErasing;
    $('deco-eraser-btn').classList.toggle('on', decoErasing);
  };
  $('deco-clear-btn').onclick = () => {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    updateDecorationPreview();
  };
  updateDecorationPreview();
}

